try:
    print('>>> x = 1j')
    print('>>> y = (1, 2)')
    print('>>> x *= y')
    print('>>> x')
    x = 1j
    y = (1, 2)
    x *= y
    print(x)
except Exception as e:
    print(type(e), ':', e)
print()
